    31	    private DocGenGenerationRunner $generationRunner;
    32	
    33	    /**
    34	     * Creates the DocGen CLI application for a project working directory.
    35	     */
    36	    public function __construct(
    37	        /** @readonly */
    38	        private string $workingDirectory,
    39	        ?Closure $stdout = null,
    40	        ?Closure $stderr = null,
    41	        ?DocGenCliArgumentParser $argumentParser = null,
    42	        ?DocGenHelpText $helpText = null,
    43	        ?DocGenGenerationRunner $generationRunner = null,
    44	    ) {
    45	        $this->writer = new DocGenOutputWriter($stdout, $stderr);
    46	        $this->argumentParser = $argumentParser ?? new DocGenCliArgumentParser();
    47	        $this->helpText = $helpText ?? new DocGenHelpText();
    48	        $this->generationRunner = $generationRunner ?? new DocGenGenerationRunner(
    49	            $this->workingDirectory,
    50	            null,
    51	            null,
    52	            null,
    53	            $this->writer,
    54	        );
    55	    }
    56	
    57	    /**
    58	     * Runs the CLI with raw process arguments.
    59	     *
    60	     * @param list<string> $argv
    61	     */
    62	    public function run(array $argv): int
    63	    {
    64	        array_shift($argv);
    65	        try {
    66	            $arguments = $this->argumentParser->parse($argv);
    67	        } catch (DocGenException $exception) {
    68	            $this->writer->writeError(sprintf("DocGen error: %s\n", $exception->getMessage()));
    69	
    70	            return 2;
    71	        }
    72	
    73	        if ($arguments['help']) {
    74	            $this->writer->write($this->helpText->text());
    75	
    76	            return 0;
    77	        }
    78	
    79	        if ($arguments['version']) {
    80	            $this->writer->write(sprintf("doc-gen %s\n", self::VERSION));
    81	
    82	            return 0;
    83	        }
    84	
    85	        return $this->generationRunner->run($arguments);
