    14	final class DocGenConfigOverrides
    15	{
    16	    /**
    17	     * Returns the cache directory a run keeps its caches in, if any.
    18	     *
    19	     * A run that was told to cache nothing caches nothing, whatever the
    20	     * project configured, because that is what the option is for.
    21	     *
    22	     * @param array{config: ?string, output: ?string, vendor: ?list<string>, vendorDev: ?list<string>, coverage: ?string, baseUrl: ?string, serve: ?string, memoryLimit: ?string, jobs: ?int, base: ?string, head: ?string, cacheDir: ?string, noCache: bool, clearCache: bool, help: bool, version: bool} $arguments
    23	     */
    24	    public function cache(DocGenConfig $config, array $arguments): ?string
    25	    {
    26	        if ($arguments['noCache']) {
    27	            return null;
    28	        }
    29	
    30	        return $arguments['cacheDir'] ?? $config->cache;
    31	    }
    32	
    33	    /**
    34	     * Rebuilds the configuration with the given CLI overrides applied.
    35	     *
    36	     * @param array{config: ?string, output: ?string, vendor: ?list<string>, vendorDev: ?list<string>, coverage: ?string, baseUrl: ?string, serve: ?string, memoryLimit: ?string, jobs: ?int, base: ?string, head: ?string, cacheDir: ?string, noCache: bool, clearCache: bool, help: bool, version: bool} $arguments
    37	     */
    38	    public function apply(DocGenConfig $config, array $arguments): DocGenConfig
    39	    {
    40	        return new DocGenConfig(
    41	            $config->root,
    42	            $config->packages,
    43	            $arguments['vendor'] !== null ? array_merge($config->vendor, $arguments['vendor']) : $config->vendor,
    44	            $config->exclude,
    45	            $arguments['output'] ?? $config->output,
    46	            $config->title,
    47	            $config->deptrac,
    48	            $arguments['coverage'] ?? $config->coverage,
    49	            $arguments['vendorDev'] !== null ? array_merge($config->vendorDev, $arguments['vendorDev']) : $config->vendorDev,
    50	            $this->cache($config, $arguments),
    51	            $arguments['baseUrl'] ?? $config->baseUrl,
    52	            $config->repository,
