    22	 * @property-read ?string $cache
    23	 * @property-read ?string $baseUrl
    24	 * @property-read ?string $repository
    25	 */
    26	final class DocGenConfig
    27	{
    28	    /**
    29	     * Where the generation caches are kept unless a project says otherwise.
    30	     */
    31	    public const DEFAULT_CACHE = 'build/doc-gen-cache';
    32	
    33	    /**
