    38	     * @param ?string $cache the cache directory, or null to cache nothing
    39	     * @param ?string $baseUrl the address the site is published at, without a trailing slash, or null when it is unknown
    40	     * @param ?string $repository the address of the repository the project lives in, or null to read it from the root package
    41	     */
    42	    public function __construct(
    43	        /** @readonly */
    44	        private string $root,
    45	        /** @readonly */
    46	        private array $packages,
    47	        /** @readonly */
