    24	final class ConfigLoader
    25	{
    26	    /** @var list<string> */
    27	    private const KNOWN_KEYS = ['packages', 'vendor', 'vendor_dev', 'exclude', 'output', 'title', 'deptrac', 'coverage', 'cache', 'base_url', 'repository'];
    28	
    29	    /** @readonly */
    30	    private ConfigScalarReader $scalarReader;
    31	
    32	    /** @readonly */
