    37	
    38	    /** @readonly */
    39	    private RepositoryUrl $repository;
    40	
    41	    /**
    42	     * Creates a config loader from YAML section readers.
    43	     */
    44	    public function __construct(
    45	        ?ConfigScalarReader $scalarReader = null,
    46	        ?ConfigStringListReader $stringListReader = null,
    47	        ?BaseUrl $baseUrl = null,
    48	        ?RepositoryUrl $repository = null,
    49	    ) {
    50	        $this->scalarReader = $scalarReader ?? new ConfigScalarReader();
    51	        $this->stringListReader = $stringListReader ?? new ConfigStringListReader();
    52	        $this->baseUrl = $baseUrl ?? new BaseUrl();
    53	        $this->repository = $repository ?? new RepositoryUrl();
    54	    }
    55	
    56	    /**
    57	     * Loads and validates a DocGen YAML configuration file.
    58	     *
    59	     * @throws DocGenException when the file is missing, unparsable, or contains invalid values
    60	     */
    61	    public function load(string $path): DocGenConfig
    62	    {
    63	        if (!is_file($path)) {
    64	            throw new DocGenException(sprintf('DocGen config not found: %s', $path));
    65	        }
    66	
    67	        try {
    68	            $data = Yaml::parseFile($path);
    69	        } catch (ParseException $exception) {
    70	            throw new DocGenException('Invalid doc.yaml: ' . $exception->getMessage(), 0, $exception);
    71	        }
    72	
    73	        if (!is_array($data)) {
    74	            throw new DocGenException('Invalid doc.yaml: top-level value must be a mapping.');
    75	        }
    76	
    77	        foreach (array_keys($data) as $key) {
    78	            if (!in_array((string) $key, self::KNOWN_KEYS, true)) {
    79	                throw new DocGenException(sprintf('Invalid doc.yaml: top-level contains unsupported key "%s".', $key));
    80	            }
    81	        }
    82	
    83	        $root = realpath(dirname($path));
    84	
    85	        return new DocGenConfig(
    86	            $root === false ? dirname($path) : $root,
    87	            $this->stringListReader->read($data, 'packages', ['.', 'packages/*']),
    88	            $this->stringListReader->read($data, 'vendor', []),
    89	            $this->stringListReader->read($data, 'exclude', []),
    90	            $this->scalarReader->string($data, 'output', 'build/docs'),
    91	            $this->scalarReader->optionalString($data, 'title'),
