 32	    public const VALUE_OPTIONS = ['config', 'output', 'coverage', 'base-url', 'memory-limit', 'jobs', 'diff', 'base', 'head', 'cache-dir'];
 33	
 34	    /** @readonly */
 35	    private BaseUrl $baseUrl;
