 37	    /**
 38	     * Creates an argument parser from its value normalizers.
 39	     */
 40	    public function __construct(?BaseUrl $baseUrl = null)
 41	    {
 42	        $this->baseUrl = $baseUrl ?? new BaseUrl();
 43	    }
