 45	    /**
 46	     * Parses argument strings into a normalized option map.
 47	     *
 48	     * @param list<string> $argv
 49	     *
 50	     * @return array{config: ?string, output: ?string, vendor: ?list<string>, vendorDev: ?list<string>, coverage: ?string, baseUrl: ?string, serve: ?string, memoryLimit: ?string, jobs: ?int, base: ?string, head: ?string, cacheDir: ?string, noCache: bool, clearCache: bool, help: bool, version: bool}
 51	     *
 52	     * @throws DocGenException when an option is unknown or lacks a value
 53	     */
 54	    public function parse(array $argv): array
 55	    {
 56	        $options = ['config' => null, 'output' => null, 'vendor' => null, 'vendorDev' => null, 'coverage' => null, 'baseUrl' => null, 'serve' => null, 'memoryLimit' => null, 'jobs' => null, 'base' => null, 'head' => null, 'cacheDir' => null, 'noCache' => false, 'clearCache' => false, 'help' => false, 'version' => false];
 57	        $count = count($argv);
 58	        for ($index = 0; $index < $count; $index++) {
 59	            $argument = $argv[$index];
 60	            if ($argument === '--help' || $argument === '-h') {
 61	                $options['help'] = true;
 62	            } elseif ($argument === '--version' || $argument === '-V') {
 63	                $options['version'] = true;
 64	            } elseif ($argument === '--no-cache') {
 65	                $options['noCache'] = true;
 66	            } elseif ($argument === '--clear-cache') {
 67	                $options['clearCache'] = true;
 68	            } elseif ($argument === '--serve') {
 69	                $options['serve'] = '127.0.0.1:8090';
 70	            } elseif (str_starts_with($argument, '--serve=')) {
 71	                $options['serve'] = $this->address(substr($argument, 8));
 72	            } elseif ($argument === '--vendor' || str_starts_with($argument, '--vendor=')) {
 73	                $options['vendor'] = $this->vendorGlobs($argument, '--vendor');
 74	            } elseif ($argument === '--vendor-dev' || str_starts_with($argument, '--vendor-dev=')) {
 75	                $options['vendorDev'] = $this->vendorGlobs($argument, '--vendor-dev');
 76	            } elseif ($this->isValueOption($argument)) {
 77	                $name = $this->optionName($argument);
 78	                $options = $this->applyValueOption($options, $name, $this->take($argv, $index, $name));
 79	                $index += $this->consumed($argument);
 80	            } else {
 81	                throw new DocGenException(sprintf('Unknown option: %s', $argument));
 82	            }
 83	        }
 84	
 85	        return $this->validated($options);
 86	    }
