 88	    /**
 89	     * Reports whether an argument selects one of the value options.
 90	     */
 91	    public function isValueOption(string $argument): bool
 92	    {
 93	        foreach (self::VALUE_OPTIONS as $name) {
 94	            if ($argument === '--' . $name || str_starts_with($argument, '--' . $name . '=')) {
 95	                return true;
 96	            }
 97	        }
 98	
 99	        return false;
100	    }
