102	    /**
103	     * Returns the name of a long option, without its inline value.
104	     */
105	    public function optionName(string $argument): string
106	    {
107	        $name = substr($argument, 2);
108	        $position = strpos($name, '=');
109	
110	        return $position === false ? $name : substr($name, 0, $position);
111	    }
