113	    /**
114	     * Applies one value option to the option map.
115	     *
116	     * @param array{config: ?string, output: ?string, vendor: ?list<string>, vendorDev: ?list<string>, coverage: ?string, baseUrl: ?string, serve: ?string, memoryLimit: ?string, jobs: ?int, base: ?string, head: ?string, cacheDir: ?string, noCache: bool, clearCache: bool, help: bool, version: bool} $options
117	     *
118	     * @return array{config: ?string, output: ?string, vendor: ?list<string>, vendorDev: ?list<string>, coverage: ?string, baseUrl: ?string, serve: ?string, memoryLimit: ?string, jobs: ?int, base: ?string, head: ?string, cacheDir: ?string, noCache: bool, clearCache: bool, help: bool, version: bool}
119	     *
120	     * @throws DocGenException when the value of the option is malformed
121	     */
122	    public function applyValueOption(array $options, string $name, string $value): array
123	    {
124	        if ($name === 'config') {
125	            $options['config'] = $value;
126	        } elseif ($name === 'output') {
127	            $options['output'] = $value;
128	        } elseif ($name === 'coverage') {
129	            $options['coverage'] = $value;
130	        } elseif ($name === 'base-url') {
131	            $options['baseUrl'] = $this->baseUrl->normalize($value);
132	        } elseif ($name === 'memory-limit') {
133	            $options['memoryLimit'] = $this->memoryLimit($value);
134	        } elseif ($name === 'jobs') {
135	            $options['jobs'] = $this->jobs($value);
136	        } elseif ($name === 'cache-dir') {
137	            $options['cacheDir'] = $value;
138	        } elseif ($name === 'base') {
139	            $options['base'] = $value;
140	        } elseif ($name === 'head') {
141	            $options['head'] = $value;
142	        } else {
143	            $options = $this->revisionRange($options, $value);
144	        }
145	
146	        return $options;
147	    }
148	
149	    /**
150	     * Splits a BASE..HEAD range into the two compared revisions.
151	     *
152	     * A range without a head compares against the working tree, which is
153	     * what a reader looking at their own uncommitted change wants.
154	     *
155	     * @param array{config: ?string, output: ?string, vendor: ?list<string>, vendorDev: ?list<string>, coverage: ?string, baseUrl: ?string, serve: ?string, memoryLimit: ?string, jobs: ?int, base: ?string, head: ?string, cacheDir: ?string, noCache: bool, clearCache: bool, help: bool, version: bool} $options
156	     *
157	     * @return array{config: ?string, output: ?string, vendor: ?list<string>, vendorDev: ?list<string>, coverage: ?string, baseUrl: ?string, serve: ?string, memoryLimit: ?string, jobs: ?int, base: ?string, head: ?string, cacheDir: ?string, noCache: bool, clearCache: bool, help: bool, version: bool}
158	     *
159	     * @throws DocGenException when the range names no base revision
160	     */
161	    public function revisionRange(array $options, string $value): array
162	    {
163	        $parts = explode('..', $value, 2);
164	        $base = trim($parts[0]);
165	        if ($base === '') {
166	            throw new DocGenException(sprintf(
167	                'Invalid --diff range: %s. Use BASE to compare against the working tree, or BASE..HEAD to compare two revisions.',
168	                $value,
169	            ));
170	        }
171	
172	        $head = count($parts) === 2 ? trim($parts[1]) : '';
173	        $options['base'] = $base;
174	        $options['head'] = $head === '' ? $options['head'] : $head;
175	
176	        return $options;
177	    }
178	
179	    /**
180	     * Rejects the option combinations that cannot be acted on.
181	     *
182	     * @param array{config: ?string, output: ?string, vendor: ?list<string>, vendorDev: ?list<string>, coverage: ?string, baseUrl: ?string, serve: ?string, memoryLimit: ?string, jobs: ?int, base: ?string, head: ?string, cacheDir: ?string, noCache: bool, clearCache: bool, help: bool, version: bool} $options
183	     *
184	     * @return array{config: ?string, output: ?string, vendor: ?list<string>, vendorDev: ?list<string>, coverage: ?string, baseUrl: ?string, serve: ?string, memoryLimit: ?string, jobs: ?int, base: ?string, head: ?string, cacheDir: ?string, noCache: bool, clearCache: bool, help: bool, version: bool}
185	     *
186	     * @throws DocGenException when a head revision has nothing to compare against
187	     */
188	    public function validated(array $options): array
189	    {
190	        if ($options['head'] !== null && $options['base'] === null) {
191	            throw new DocGenException('Option --head needs a revision to compare against: add --base=REVISION, or use --diff=BASE..HEAD.');
192	        }
193	
194	        return $options;
195	    }
196	
197	    /**
198	     * Returns the inline value of a long option, or null.
199	     */
200	    public function valueOption(string $argument, string $name): ?string
201	    {
202	        $prefix = '--' . $name . '=';
203	        if (str_starts_with($argument, $prefix)) {
204	            $value = substr($argument, strlen($prefix));
205	
206	            return $value !== '' ? $value : null;
207	        }
208	
209	        return null;
210	    }
211	
212	    /**
213	     * Returns the value of an option at the current position.
214	     *
215	     * @param list<string> $argv
216	     *
217	     * @throws DocGenException when the option has no value
218	     */
219	    public function take(array $argv, int $index, string $name): string
220	    {
221	        $inline = $this->valueOption($argv[$index], $name);
222	        if ($inline !== null) {
223	            return $inline;
224	        }
225	
226	        $next = $argv[$index + 1] ?? null;
227	        if ($next === null || str_starts_with($next, '-')) {
228	            throw new DocGenException(sprintf('Option --%s requires a value.', $name));
229	        }
230	
231	        return $next;
232	    }
233	
234	    /**
235	     * Returns how many extra arguments a value option consumed.
236	     */
237	    public function consumed(string $argument): int
238	    {
239	        return str_contains($argument, '=') ? 0 : 1;
240	    }
241	
242	    /**
243	     * Returns the package name globs of a vendor option.
244	     *
245	     * The bare option without a value means every installed package, so it
246	     * expands to the match-all glob.
247	     *
248	     * @param string $argument the raw argument, such as --vendor-dev=acme/*
249	     * @param string $option the option name, such as --vendor-dev
250	     *
251	     * @return list<string>
252	     *
253	     * @throws DocGenException when the option has a value without any glob
254	     */
255	    public function vendorGlobs(string $argument, string $option): array
256	    {
257	        if ($argument === $option) {
258	            return ['*'];
259	        }
260	
261	        return $this->globList(substr($argument, strlen($option) + 1), $option);
262	    }
263	
264	    /**
265	     * Splits a comma-separated glob list.
266	     *
267	     * @param string $option the option name quoted in the error message
268	     *
269	     * @return list<string>
270	     *
271	     * @throws DocGenException when the list is empty
272	     */
273	    public function globList(string $value, string $option): array
274	    {
275	        $globs = [];
276	        foreach (explode(',', $value) as $glob) {
277	            $trimmed = trim($glob);
278	            if ($trimmed !== '') {
279	                $globs[] = $trimmed;
280	            }
281	        }
282	
283	        if ($globs === []) {
284	            throw new DocGenException(sprintf('Option %s requires at least one package name glob.', $option));
285	        }
286	
287	        return $globs;
288	    }
289	
290	    /**
291	     * Validates a memory limit value such as 512M, 1G, or -1.
292	     *
293	     * @throws DocGenException when the value is malformed
294	     */
295	    public function memoryLimit(string $value): string
296	    {
297	        if (preg_match('/^(-1|\d+[KMG]?)$/i', $value) !== 1) {
298	            throw new DocGenException(sprintf('Invalid --memory-limit value: %s. Use a byte count, a value such as 512M or 1G, or -1 for no limit.', $value));
299	        }
300	
301	        return $value;
302	    }
303	
304	    /**
305	     * Validates a worker count such as 4, or 1 for a sequential run.
306	     *
307	     * @throws DocGenException when the value is not a positive number
308	     */
309	    public function jobs(string $value): int
310	    {
311	        if (preg_match('/^[1-9]\d*$/', $value) !== 1) {
312	            throw new DocGenException(sprintf('Invalid --jobs value: %s. Use a worker count of 1 or more, or leave it out to use the cores of this machine.', $value));
313	        }
314	
315	        return (int) $value;
316	    }
317	
318	    /**
319	     * Normalizes a serve address, accepting a bare port number.
320	     *
321	     * @throws DocGenException when the address is malformed
322	     */
323	    public function address(string $value): string
324	    {
325	        if (preg_match('/^\d+$/', $value) === 1) {
326	            return '127.0.0.1:' . $value;
327	        }
328	
329	        if (preg_match('/^[A-Za-z0-9_.\[\]-]+:\d+$/', $value) === 1) {
330	            return $value;
331	        }
332	
333	        throw new DocGenException(sprintf('Invalid --serve address: %s. Use HOST:PORT or a port number.', $value));
334	    }
335	}

