 72	    /**
 73	     * Creates a generation runner from pipeline collaborators.
 74	     */
 75	    public function __construct(
 76	        string $workingDirectory,
 77	        ?ConfigLoader $configLoader = null,
 78	        ?ProjectAnalyzer $analyzer = null,
 79	        ?SiteRenderer $siteRenderer = null,
 80	        ?DocGenOutputWriter $writer = null,
 81	        ?DocGenConfigPathResolver $configPathResolver = null,
 82	        ?DocGenConfigOverrides $overrides = null,
 83	        ?DocGenPathResolver $pathResolver = null,
 84	        ?DocGenPreviewServer $previewServer = null,
 85	        ?DocGenMemoryLimit $memoryLimit = null,
 86	        ?DiffWorkspace $workspace = null,
 87	        ?CacheStore $store = null,
 88	        ?SocialCard $card = null,
 89	    ) {
 90	        $this->workingDirectory = $workingDirectory;
 91	        $this->configLoader = $configLoader ?? new ConfigLoader();
 92	        $this->analyzer = $analyzer ?? new ProjectAnalyzer();
 93	        $this->siteRenderer = $siteRenderer ?? new SiteRenderer();
 94	        $this->writer = $writer ?? new DocGenOutputWriter();
 95	        $this->configPathResolver = $configPathResolver ?? new DocGenConfigPathResolver();
 96	        $this->overrides = $overrides ?? new DocGenConfigOverrides();
 97	        $this->pathResolver = $pathResolver ?? new DocGenPathResolver();
 98	        $this->previewServer = $previewServer ?? new DocGenPreviewServer();
 99	        $this->memoryLimit = $memoryLimit ?? new DocGenMemoryLimit();
100	        $this->workspace = $workspace ?? new DiffWorkspace(null, null, $this->analyzer);
101	        $this->store = $store ?? new CacheStore();
102	        $this->card = $card ?? new SocialCard();
103	    }
