105	    /**
106	     * Generates the site and optionally serves it.
107	     *
108	     * @param array{config: ?string, output: ?string, vendor: ?list<string>, vendorDev: ?list<string>, coverage: ?string, baseUrl: ?string, serve: ?string, memoryLimit: ?string, jobs: ?int, base: ?string, head: ?string, cacheDir: ?string, noCache: bool, clearCache: bool, help: bool, version: bool} $arguments
109	     */
110	    public function run(array $arguments): int
111	    {
112	        $this->memoryLimit->apply($arguments['memoryLimit']);
113	
114	        try {
115	            $loaded = $this->loadConfig($arguments['config']);
116	            $config = $this->overrides->apply($loaded, $arguments);
117	            $outputRoot = $this->pathResolver->resolve($config->root, $config->output);
118	            if ($arguments['clearCache']) {
119	                $this->clear($config->root, $arguments['cacheDir'] ?? $loaded->cache);
120	            }
121	
122	            $cache = $this->caches($config, $outputRoot);
123	            $result = $arguments['base'] === null
124	                ? $this->generate($config, $outputRoot, $arguments['jobs'], $cache)
125	                : $this->generateDiff($config, $outputRoot, new RevisionRange($arguments['base'], $arguments['head']), $arguments['jobs'], $cache);
126	            $this->report($result['model'], $result['pages'], $outputRoot, $cache);
127	
128	            if ($arguments['serve'] !== null) {
129	                $this->writer->write(sprintf("Serving documentation at http://%s (Ctrl-C to stop)\n", $arguments['serve']));
130	
131	                return $this->previewServer->serve($outputRoot, $arguments['serve']);
132	            }
133	        } catch (DocGenException $exception) {
134	            $this->writer->writeError(sprintf("DocGen error: %s\n", $exception->getMessage()));
135	
136	            return 2;
137	        }
138	
139	        return 0;
140	    }
