142	    /**
143	     * Analyzes and renders the documented project as it is now.
144	     *
145	     * @return array{model: ProjectModel, pages: int}
146	     *
147	     * @throws DocGenException when the project cannot be analyzed or written
148	     */
149	    public function generate(DocGenConfig $config, string $outputRoot, ?int $workers = null, ?GenerationCache $cache = null): array
150	    {
151	        $cache = $cache ?? new GenerationCache();
152	        $model = $this->analyzer->analyze($config, $workers, $cache->sources);
153	
154	        return ['model' => $model, 'pages' => $this->siteRenderer->render($model, $outputRoot, null, $workers, $cache->pages)];
155	    }
