157	    /**
158	     * Builds the caches of one run, or the absence of them.
159	     *
160	     * Both caches are read before anything is analyzed or rendered, so the
161	     * worker processes of the run inherit them instead of reading the same
162	     * files once per worker.
163	     */
164	    public function caches(DocGenConfig $config, string $outputRoot): GenerationCache
165	    {
166	        if ($config->cache === null) {
167	            return new GenerationCache();
168	        }
169	
170	        $directory = $this->pathResolver->resolve($config->root, $config->cache);
171	        if (!$this->store->prepare($directory)) {
172	            $this->writer->writeError(sprintf("Warning: nothing is cached, because the cache directory cannot be written: %s\n", $directory));
173	
174	            return new GenerationCache();
175	        }
176	
177	        $cache = new GenerationCache(new ParseCache($directory), new RenderCache($directory, $outputRoot));
178	        $cache->load();
179	
180	        return $cache;
181	    }
182	
183	    /**
184	     * Removes one cache directory before the run that was told to.
185	     */
186	    public function clear(string $root, ?string $directory): void
187	    {
188	        if ($directory !== null) {
189	            $this->store->clear($this->pathResolver->resolve($root, $directory));
190	        }
191	    }
192	
193	    /**
194	     * Renders the documented project as the comparison of two revisions.
195	     *
196	     * The checkouts of the compared revisions are removed again whatever
197	     * happens while the site is written, because they are scratch copies
198	     * of the repository and nothing may outlive the run.
199	     *
200	     * @return array{model: ProjectModel, pages: int}
201	     *
202	     * @throws DocGenException when a revision cannot be read or analyzed
203	     */
204	    public function generateDiff(DocGenConfig $config, string $outputRoot, RevisionRange $range, ?int $workers = null, ?GenerationCache $cache = null): array
205	    {
206	        $cache = $cache ?? new GenerationCache();
207	        $session = $this->workspace->open($config, $range, $workers, $cache->sources);
208	
209	        try {
210	            $pages = $this->siteRenderer->render($session->model, $outputRoot, $session->diff, $workers, $cache->pages);
211	            $this->writer->write(sprintf(
212	                "Compared %s to %s\n",
213	                $session->diff->baseLabel(),
214	                $session->diff->headLabel(),
215	            ));
216	
217	            return ['model' => $session->model, 'pages' => $pages];
218	        } finally {
219	            $this->workspace->close($session);
220	        }
221	    }
