223	    /**
224	     * Reports what was written and what the analysis could not do.
225	     */
226	    public function report(ProjectModel $model, int $pages, string $outputRoot, ?GenerationCache $cache = null): void
227	    {
228	        $this->writer->write(sprintf(
229	            "Generated %d pages for %d packages into %s\n",
230	            $pages,
231	            count($model->packages),
232	            $outputRoot,
233	        ));
234	        if ($cache !== null) {
235	            $this->reportCache($cache);
236	        }
237	
238	        foreach ($model->warnings as $warning) {
239	            $this->writer->writeError(sprintf("Warning: %s\n", $warning));
240	        }
241	
242	        if ($model->baseUrl !== null && !$this->card->supported()) {
243	            $this->writer->writeError(
244	                'Warning: no social preview image was drawn, because the gd extension with FreeType support is missing.'
245	                . " The pages carry their preview tags without an image.\n",
246	            );
247	        }
248	    }
249	
250	    /**
251	     * Writes what the caches held back and keeps what this run learned.
252	     */
253	    public function reportCache(GenerationCache $cache): void
254	    {
255	        $summary = $cache->summary();
256	        if ($summary !== null) {
257	            $this->writer->write($summary . "\n");
258	        }
259	
260	        $cache->save();
261	    }
262	
263	    /**
264	     * Loads the configuration file, or builds the zero-config defaults.
265	     *
266	     * @throws DocGenException when an explicitly given config file is invalid
267	     */
268	    public function loadConfig(?string $configOption): DocGenConfig
269	    {
270	        if ($configOption !== null) {
271	            return $this->configLoader->load($this->configPathResolver->resolve($this->workingDirectory, $configOption));
272	        }
273	
274	        $default = $this->configPathResolver->resolve($this->workingDirectory, 'doc.yaml');
275	        if (is_file($default)) {
276	            return $this->configLoader->load($default);
277	        }
278	
279	        $root = realpath($this->workingDirectory);
280	
281	        return new DocGenConfig($root === false ? $this->workingDirectory : $root, ['.', 'packages/*'], [], [], 'build/docs', null, null, null);
282	    }
