30	     *
31	     * Anything that is not an absolute http address is no address at all
32	     * here, because a page can only link to what a browser can follow.
33	     */
34	    public function read(mixed $value): ?string
35	    {
36	        if (!is_string($value)) {
37	            return null;
38	        }
39	
40	        $trimmed = trim($value);
41	        if (preg_match('#^https?://[^\s/?\#]+(/[^\s?\#]*)?$#', $trimmed) !== 1) {
42	            return null;
43	        }
44	
45	        return rtrim($trimmed, '/');
46	    }
47	
48	    /**
49	     * Returns one configured address without its trailing slash.
50	     *
51	     * An empty value is the same answer as no value at all: the site names
52	     * no repository, rather than one that resolves nowhere.
53	     *
54	     * @throws DocGenException when the value is not an absolute http address
55	     */
56	    public function normalize(?string $value): ?string
