41	                if (!isset($argv[$index + 1]) || str_starts_with($argv[$index + 1], '-')) {
42	                    throw new ScopeGuardException(sprintf('Missing value for %s.', '--config'));
43	                }
44	                $arguments['config'] = $argv[++$index];
45	            } elseif (str_starts_with($arg, '--config=')) {
46	                $arguments['config'] = substr($arg, 9);
47	            } elseif ($arg === '--reporter' || $arg === '--format') {
48	                if (!isset($argv[$index + 1]) || str_starts_with($argv[$index + 1], '-')) {
49	                    throw new ScopeGuardException(sprintf('Missing value for %s.', $arg));
50	                }
51	                $arguments['reporter'] = $argv[++$index];
52	            } elseif (str_starts_with($arg, '--reporter=')) {
53	                $arguments['reporter'] = substr($arg, 11);
54	            } elseif (str_starts_with($arg, '--format=')) {
55	                $arguments['reporter'] = substr($arg, 9);
56	            } else {
57	                throw new ScopeGuardException(sprintf('Unknown option: %s', $arg));
58	            }
59	        }
