import re, glob

NEW_ORDER = ['packages','vendor','vendorDev','exclude','output','title','deptrac','coverage','cacheDir','baseUrl','repository','serve','memoryLimit','jobs','base','head','noCache','clearCache','help','version']
DEFAULTS = {k: ('false' if k in ('noCache','clearCache','help','version') else 'null') for k in NEW_ORDER}

def split_top(s):
    parts, depth, cur, quote = [], 0, '', None
    for ch in s:
        if quote:
            cur += ch
            if ch == quote:
                quote = None
            continue
        if ch in "'\"":
            quote = ch; cur += ch; continue
        if ch in '[(':
            depth += 1
        elif ch in ')]':
            depth -= 1
        if ch == ',' and depth == 0:
            parts.append(cur.strip()); cur = ''
            continue
        cur += ch
    if cur.strip():
        parts.append(cur.strip())
    return parts

pattern = re.compile(r"\['config' => .*?'version' => (?:true|false)\]")

def rewrite(match):
    inner = match.group(0)[1:-1]
    pairs = {}
    for part in split_top(inner):
        k, v = part.split('=>', 1)
        pairs[k.strip().strip("'")] = v.strip()
    pairs.pop('config', None)
    out = []
    for key in NEW_ORDER:
        out.append("'%s' => %s" % (key, pairs.get(key, DEFAULTS[key])))
    return '[' + ', '.join(out) + ']'

for path in glob.glob('tests/**/*.php', recursive=True):
    s = open(path).read()
    new, n = pattern.subn(rewrite, s)
    if n:
        open(path,'w').write(new)
        print(path, n)
